  if (memo.has(n)) return memo.get(n);
  let best = minSteps(n - 1, memo);
  if (n % 2 === 0) best = Math.min(best, minSteps(n / 2, memo));
  if (n % 3 === 0) best = Math.min(best, minSteps(n / 3, memo));
  memo.set(n, 1 + best);
