function minSteps(n) {
  const dp = new Array(n + 1).fill(0);             // dp[i]: fewest steps from i down to 1
  for (let i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + 1;                         // subtract 1
    if (i % 2 === 0) dp[i] = Math.min(dp[i], dp[i / 2] + 1);   // or divide by 2
    if (i % 3 === 0) dp[i] = Math.min(dp[i], dp[i / 3] + 1);   // or divide by 3
  }
  return dp[n];
}

